WITH metrics AS (SELECT *, LAST_VALUE(segment, TRUE) OVER (ORDER BY signup_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_segment, SUM(age) OVER w_grp AS cumulative_age FROM customers WINDOW w_grp AS (PARTITION BY city ORDER BY signup_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT id, name, email, country, city, segment, signup_date, is_active, credit_limit FROM metrics ORDER BY credit_limit DESC
